    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    # Complete the outer bounding-box frame.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if r in (r0, r1) or c in (c0, c1):
                if grid[r][c] == bg: out[r][c] = 2
    # Also bridge gaps on any row/column with at least four foreground cells.
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == mark]
        if len(cs) >= 4:
            for c in range(cs[0], cs[-1] + 1):
                if grid[r][c] == bg: out[r][c] = 2
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] == mark]
        if len(rs) >= 4:
            for r in range(rs[0], rs[-1] + 1):
                if grid[r][c] == bg: out[r][c] = 2
    return out
